pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how much space we waste in 
        // existing bins by not using them.
        score = 50.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Best-Fit Decreasing logic: heavily favor tight fits.
        // Post-residual is already part of the score.

        // If this is the last chance to fit into an existing bin (fitting_bins_count == 1),
        // apply a massive discount to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Lookahead penalty: if the next item is large and won't fit in the current post_residual,
        // penalize this placement to keep space available for the lookahead.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 15.0;
        }

        // Global pressure: if we have many bins open, try to pack tighter by penalizing
        // large post_residuals more aggressively as the stream progresses.
        score += (open_bins_count as f64 * 0.2) * progress;

        // Anti-fragmentation: penalize small residuals that are likely to become dead space 
        // (e.g., leaving 1-5 units of space is usually bad).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: penalize large post_residuals (waste)
    // We favor the tightest fit (smallest post_residual).

    // 2. Lookahead penalty: If the next item is large, avoid leaving a tiny residual 
    // that won't fit common item sizes (e.g., < 10).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // High penalty if we create a "dead" gap that cannot fit the next item
            score += 40.0;
        } else if post_residual >= next_item_size {
            // Reward if we preserve space specifically for the next item
            score -= 15.0;
        }
    }

    // 3. Harmonic class awareness: 
    // If post_residual is a multiple of common item size ranges, it's more "reusable".
    // Penalize odd residuals that create fragmented space.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 4. Thresholding for new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless all other options are extremely poor (i.e., cause significant fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open if no bins exist
        } else {
            // Only open a new bin if the average waste of existing bins is high.
            score += 35.0 + (mean_residual * 0.5);
        }
    }

    // 5. Urgency: If this is the last chance to fit an item into an existing bin
    // (fitting_bins_count == 1), prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress scaling: As the stream nears the end, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

