pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit behavior (minimize post_residual)
    // 2. Harmonic penalty: penalize small remainders that cannot fit likely future items
    // If post_residual is in the range [1, 9], it's a "dead zone" (too small for any item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave a multiple of common item sizes (e.g., 20, 25, 33).
    // This helps align bin residuals for future packing density.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New bin penalty: Heavily penalize opening a new bin unless the existing fit is extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if we have many open bins already or if the fit is terrible.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin.
            score = 0.0;
        }
    }

    // 6. Global progression adjustment: As the stream nears the end, be more aggressive 
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best-Fit principle).
    // Lower residual is generally better to minimize wasted space.
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily unless we are at the start or desperate.
    if is_new_bin {
        // If we have other options, penalize new bins significantly.
        if fitting_bins_count > 0 {
            score += 150.0 + (progress * 50.0);
        } else {
            // If no other options, this is the baseline for opening a bin.
            score = 100.0;
        }
    }

    // 2. Lookahead logic: if the next item is large, prioritize leaving enough space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot fit the next item if it's large.
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward creating a bin that fits the next item perfectly.
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
        }
    }

    // 3. Global state balancing: encourage filling bins that are already "below average" 
    // to keep the distribution of residuals tight.
    if !is_new_bin {
        let residual_diff = bin_residual as f64 - mean_residual;
        if residual_diff > 0.0 {
            // Heavily favor bins that have more space than the current average.
            score -= residual_diff * 0.5;
        }
    }

    // 4. Dynamic pressure: as we approach the end of the stream, 
    // tighten the tolerance for creating new bins.
    if progress > 0.8 && !is_new_bin {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Favor Best-Fit (small post_residual) while penalizing fragmentation
    // and using lookahead to keep space for future items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is small but not zero, it's often better to have used a different bin.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead utility: If next_item can fit in this bin, reward that placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global state awareness: If we are near the end of the stream, 
    // be more aggressive in packing to avoid opening new bins.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only pick it if we are desperate or if the current packing is truly inefficient.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        score += 45.0;
        // Dynamically lower the penalty if we have many open bins that are nearly full
        // or if we have very few options to fit the current item.
        score -= (open_bins_count as f64 * 0.5);
        score -= (fitting_bins_count as f64 * 2.0);
    } else {
        // Encourage using bins that are already "half-used" to keep residuals balanced.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score += (fill_ratio - 0.5).abs() * 5.0;
    }

    // 5. Penalize bins that deviate significantly from the mean residual
    // to keep the packing density uniform across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}
